#include <stdio.h>
struct date
{
    int y;
    int m;
    int d;
};
int leap(int y)
{
    return (y % 4 == 0 && y % 100 != 0) || y % 400 == 0;
}
int day_of_year(struct date t)
{
    int days[13] = {0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
    int i, s = t.d;
    if (leap(t.y))
        days[2] = 29;
    for (i = 1; i < t.m; i++)
        s += days[i];
    return s;
}
long total_day(struct date t)
{
    long s = 0;
    int y;
    for (y = 1; y < t.y; y++)
        s += leap(y) ? 366 : 365;
    return s + day_of_year(t);
}
int main(void)
{
    struct date a, b;
    long d;
    scanf("%d%d%d%d%d%d", &a.y, &a.m, &a.d, &b.y, &b.m, &b.d);
    d = total_day(b) - total_day(a);
    if (d < 0)
        d = -d;
    printf("days=%ld\n", d);
    return 0;
}
